/* ============ CONTENUTI DEL LIBRO: 14 zone × 10 argomenti ============
   T(emoji, titolo, testo, scena, domanda, risposta giusta, risposte sbagliate separate da "|", perché)
   scena: "emoji:animazione emoji:animazione …" — il primo è il protagonista
   Animazioni: bob jump wobble shake pulse spin flicker rise drip glow ring drive wave float twinkle */
const T = (e, t, x, s, q, ok, ko, why) => ({ e, t, x, s, q, o: [[ok, true], ...ko.split('|').map(k => [k, false])], why });

